import 'package:flutter/material.dart';
import '../../core/app_state.dart';
import '../notes/notes_screen.dart'; import '../tasks/tasks_screen.dart'; import '../focus/focus_screen.dart'; import '../library/library_screen.dart'; import '../import/import_screen.dart'; import '../settings/settings_screen.dart';
class HomeScreen extends StatefulWidget { final AppState state; const HomeScreen({super.key,required this.state}); @override State<HomeScreen> createState()=>_HomeScreenState(); }
class _HomeScreenState extends State<HomeScreen>{int index=0;
  @override Widget build(BuildContext context){final pages=[dashboard(),NotesScreen(state:widget.state),TasksScreen(state:widget.state),FocusScreen(state:widget.state),LibraryScreen(state:widget.state),ImportScreen(state:widget.state),SettingsScreen(state:widget.state)];
    return Scaffold(appBar:AppBar(title:const Text('Focus Companion 2.0'),actions:[IconButton(onPressed:widget.state.toggleLanguage,icon:const Icon(Icons.language))]),body:pages[index],bottomNavigationBar:NavigationBar(selectedIndex:index>4?0:index,onDestinationSelected:(i)=>setState(()=>index=i),destinations:const[NavigationDestination(icon:Icon(Icons.home_outlined),label:'Home'),NavigationDestination(icon:Icon(Icons.note_outlined),label:'Notes'),NavigationDestination(icon:Icon(Icons.check_circle_outline),label:'Tasks'),NavigationDestination(icon:Icon(Icons.timer_outlined),label:'Focus'),NavigationDestination(icon:Icon(Icons.folder_outlined),label:'Library')]),floatingActionButton:index<5?FloatingActionButton.extended(onPressed:()=>setState(()=>index=5),icon:const Icon(Icons.add),label:const Text('Import')):null); }
  Widget dashboard()=>ListView(padding:const EdgeInsets.all(16),children:[Text(widget.state.english?'Your second brain':'የእርስዎ ሁለተኛ አእምሮ',style:Theme.of(context).textTheme.headlineMedium),Text('Ethiopian date • ${DateTime.now().toIso8601String().split('T').first}'),const SizedBox(height:16),tile(Icons.note,'Notes','${widget.state.notes.length}',1),tile(Icons.check_circle,'Open tasks','${widget.state.tasks.where((t)=>!t.completed).length}',2),tile(Icons.folder,'Library','${widget.state.library.length} files',4),tile(Icons.timer,'Focus','25 / 50 / 90 minute sessions',3),tile(Icons.file_download,'Import Center','Books • images • documents • notes',5),const Card(child:ListTile(leading:Icon(Icons.security),title:Text('Privacy'),subtitle:Text('Local-first prototype. Cloud/LAN sync is not enabled.')))]);
  Widget tile(IconData i,String t,String s,int p)=>Card(child:ListTile(leading:Icon(i),title:Text(t),subtitle:Text(s),onTap:()=>setState(()=>index=p)));
}
